+package io.opentelemetry.javaagent.bootstrap.rabbitmq;
+
+/** Coordinates process telemetry ownership between Spring Rabbit and RabbitMQ instrumentations. */
+public final class RabbitMqConsumerProcessTracing {
+
+  private static final ThreadLocal<Integer> springListenerRegistrationDepth = new ThreadLocal<>();
+
+  /** Enters a Spring listener consumer registration and returns a non-zero restoration token. */
+  public static int enterSpringListenerRegistration() {
+    Integer currentDepth = springListenerRegistrationDepth.get();
+    int newDepth = currentDepth == null ? 1 : currentDepth + 1;
+    springListenerRegistrationDepth.set(newDepth);
+    return newDepth;
+  }
+
+  /**
+   * Restores the registration state associated with {@code token}. A zero token indicates that no
+   * registration state was entered and is a no-op.
+   */
+  public static void restore(int token) {
+    if (token == 0) {
+      return;
+    }
+
+    Integer currentDepth = springListenerRegistrationDepth.get();
+    if (currentDepth == null || currentDepth != token) {
+      return;
+    }
+
+    if (token == 1) {
+      springListenerRegistrationDepth.remove();
+    } else {
+      springListenerRegistrationDepth.set(token - 1);
+    }

